1	package com.termux.terminal;
2	
3	import java.util.Arrays;
4	
5	/**
6	 * A circular buffer of {@link TerminalRow}:s which keeps notes about what is visible on a logical screen and the scroll
7	 * history.
8	 * <p>
9	 * See {@link #externalToInternalRow(int)} for how to map from logical screen rows to array indices.
10	 */
11	public final class TerminalBuffer {
12	
13	    TerminalRow[] mLines;
14	    /** The length of {@link #mLines}. */
15	    int mTotalRows;
16	    /** The number of rows and columns visible on the screen. */
17	    int mScreenRows, mColumns;
18	    /** The number of rows kept in history. */
19	    private int mActiveTranscriptRows = 0;
20	    /** The index in the circular buffer where the visible screen starts. */
21	    private int mScreenFirstRow = 0;
22	
23	    /**
24	     * Create a transcript screen.
25	     *
26	     * @param columns    the width of the screen in characters.
27	     * @param totalRows  the height of the entire text area, in rows of text.
28	     * @param screenRows the height of just the screen, not including the transcript that holds lines that have scrolled off
29	     *                   the top of the screen.
30	     */
31	    public TerminalBuffer(int columns, int totalRows, int screenRows) {
32	        mColumns = columns;
33	        mTotalRows = totalRows;
34	        mScreenRows = screenRows;
35	        mLines = new TerminalRow[totalRows];
36	
37	        blockSet(0, 0, columns, screenRows, ' ', TextStyle.NORMAL);
38	    }
39	
40	    public String getTranscriptText() {
41	        return getSelectedText(0, -getActiveTranscriptRows(), mColumns, mScreenRows).trim();
42	    }
43	
44	    public String getTranscriptTextWithoutJoinedLines() {
45	        return getSelectedText(0, -getActiveTranscriptRows(), mColumns, mScreenRows, false).trim();
46	    }
47	
48	    public String getTranscriptTextWithFullLinesJoined() {
49	        return getSelectedText(0, -getActiveTranscriptRows(), mColumns, mScreenRows, true, true).trim();
50	    }
51	
52	    public String getSelectedText(int selX1, int selY1, int selX2, int selY2) {
53	        return getSelectedText(selX1, selY1, selX2, selY2, true);
54	    }
55	
56	    public String getSelectedText(int selX1, int selY1, int selX2, int selY2, boolean joinBackLines) {
57	        return getSelectedText(selX1, selY1, selX2, selY2, joinBackLines, false);
58	    }
59	
60	    public String getSelectedText(int selX1, int selY1, int selX2, int selY2, boolean joinBackLines, boolean joinFullLines) {
61	        final StringBuilder builder = new StringBuilder();
62	        final int columns = mColumns;
63	
64	        if (selY1 < -getActiveTranscriptRows()) selY1 = -getActiveTranscriptRows();
65	        if (selY2 >= mScreenRows) selY2 = mScreenRows - 1;
66	
67	        for (int row = selY1; row <= selY2; row++) {
68	            int x1 = (row == selY1) ? selX1 : 0;
69	            int x2;
70	            if (row == selY2) {
71	                x2 = Math.min(selX2 + 1, columns);
72	            } else {
73	                x2 = columns;
74	            }
75	            TerminalRow lineObject = mLines[externalToInternalRow(row)];
76	            int x1Index = lineObject.findStartOfColumn(x1);
77	            int x2Index = (x2 < mColumns) ? lineObject.findStartOfColumn(x2) : lineObject.getSpaceUsed();
78	            if (x2Index == x1Index) {
79	                // Selected the start of a wide character.
80	                x2Index = lineObject.findStartOfColumn(x2 + 1);
81	            }
82	            char[] line = lineObject.mText;
83	            int lastPrintingCharIndex = -1;
84	            int i;
85	            boolean rowLineWrap = getLineWrap(row);
86	            if (rowLineWrap && x2 == columns) {
87	                // If the line was wrapped, we shouldn't lose trailing space:
88	                lastPrintingCharIndex = x2Index - 1;
89	            } else {
90	                for (i = x1Index; i < x2Index; ++i) {
91	                    char c = line[i];
92	                    if (c != ' ') lastPrintingCharIndex = i;
93	                }
94	            }
95	
96	            int len = lastPrintingCharIndex - x1Index + 1;
97	            if (lastPrintingCharIndex != -1 && len > 0)
98	                builder.append(line, x1Index, len);
99	
100	            boolean lineFillsWidth = lastPrintingCharIndex == x2Index - 1;
101	            if ((!joinBackLines || !rowLineWrap) && (!joinFullLines || !lineFillsWidth)
102	                && row < selY2 && row < mScreenRows - 1) builder.append('\n');
103	        }
104	        return builder.toString();
105	    }
106	
107	    public String getWordAtLocation(int x, int y) {
108	        // Set y1 and y2 to the lines where the wrapped line starts and ends.
109	        // I.e. if a line that is wrapped to 3 lines starts at line 4, and this
110	        // is called with y=5, then y1 would be set to 4 and y2 would be set to 6.
111	        int y1 = y;
112	        int y2 = y;
113	        while (y1 > 0 && !getSelectedText(0, y1 - 1, mColumns, y, true, true).contains("\n")) {
114	            y1--;
115	        }
116	        while (y2 < mScreenRows && !getSelectedText(0, y, mColumns, y2 + 1, true, true).contains("\n")) {
117	            y2++;
118	        }
119	
120	        // Get the text for the whole wrapped line
121	        String text = getSelectedText(0, y1, mColumns, y2, true, true);
122	        // The index of x in text
123	        int textOffset = (y - y1) * mColumns + x;
124	
125	        if (textOffset >= text.length()) {
126	          // The click was to the right of the last word on the line, so
127	          // there's no word to return
128	          return "";
129	        }
130	
131	        // Set x1 and x2 to the indices of the last space before x and the
132	        // first space after x in text respectively
133	        int x1 = text.lastIndexOf(' ', textOffset);
134	        int x2 = text.indexOf(' ', textOffset);
135	        if (x2 == -1) {
136	            x2 = text.length();
137	        }
138	
139	        if (x1 == x2) {
140	          // The click was on a space, so there's no word to return
141	          return "";
142	        }
143	        return text.substring(x1 + 1, x2);
144	    }
145	
146	    public int getActiveTranscriptRows() {
147	        return mActiveTranscriptRows;
148	    }
149	
150	    public int getActiveRows() {
151	        return mActiveTranscriptRows + mScreenRows;
152	    }
153	
154	    /**
155	     * Convert a row value from the public external coordinate system to our internal private coordinate system.
156	     *
157	     * <pre>
158	     * - External coordinate system: -mActiveTranscriptRows to mScreenRows-1, with the screen being 0..mScreenRows-1.
159	     * - Internal coordinate system: the mScreenRows lines starting at mScreenFirstRow comprise the screen, while the
160	     *   mActiveTranscriptRows lines ending at mScreenFirstRow-1 form the transcript (as a circular buffer).
161	     *
162	     * External ↔ Internal:
163	     *
164	     * [ ...                            ]     [ ...                                     ]
165	     * [ -mActiveTranscriptRows         ]     [ mScreenFirstRow - mActiveTranscriptRows ]
166	     * [ ...                            ]     [ ...                                     ]
167	     * [ 0 (visible screen starts here) ]  ↔  [ mScreenFirstRow                         ]
168	     * [ ...                            ]     [ ...                                     ]
169	     * [ mScreenRows-1                  ]     [ mScreenFirstRow + mScreenRows-1         ]
170	     * </pre>
171	     *
172	     * @param externalRow a row in the external coordinate system.
173	     * @return The row corresponding to the input argument in the private coordinate system.
174	     */
175	    public int externalToInternalRow(int externalRow) {
176	        if (externalRow < -mActiveTranscriptRows || externalRow > mScreenRows)
177	            throw new IllegalArgumentException("extRow=" + externalRow + ", mScreenRows=" + mScreenRows + ", mActiveTranscriptRows=" + mActiveTranscriptRows);
178	        final int internalRow = mScreenFirstRow + externalRow;
179	        return (internalRow < 0) ? (mTotalRows + internalRow) : (internalRow % mTotalRows);
180	    }
181	
182	    public void setLineWrap(int row) {
183	        mLines[externalToInternalRow(row)].mLineWrap = true;
184	    }
185	
186	    public boolean getLineWrap(int row) {
187	        return mLines[externalToInternalRow(row)].mLineWrap;
188	    }
189	
190	    public void clearLineWrap(int row) {
191	        mLines[externalToInternalRow(row)].mLineWrap = false;
192	    }
193	
194	    /**
195	     * Resize the screen which this transcript backs. Currently, this only works if the number of columns does not
196	     * change or the rows expand (that is, it only works when shrinking the number of rows).
197	     *
198	     * @param newColumns The number of columns the screen should have.
199	     * @param newRows    The number of rows the screen should have.
200	     * @param cursor     An int[2] containing the (column, row) cursor location.
201	     */
202	    public void resize(int newColumns, int newRows, int newTotalRows, int[] cursor, long currentStyle, boolean altScreen) {
203	        // newRows > mTotalRows should not normally happen since mTotalRows is TRANSCRIPT_ROWS (10000):
204	        if (newColumns == mColumns && newRows <= mTotalRows) {
205	            resizeRowsOnly(newRows, newTotalRows, cursor, currentStyle, altScreen);
206	        } else {
207	            resizeWithReflow(newColumns, newRows, newTotalRows, cursor, currentStyle);
208	        }
209	        // Handle cursor scrolling off screen:
210	        if (cursor[0] < 0 || cursor[1] < 0) cursor[0] = cursor[1] = 0;
211	    }
212	
213	    /** Fast resize where only the row count changed (columns unchanged). */
214	    private void resizeRowsOnly(int newRows, int newTotalRows, int[] cursor, long currentStyle, boolean altScreen) {
215	        // Fast resize where just the rows changed.
216	        int shiftDownOfTopRow = mScreenRows - newRows;
217	        if (shiftDownOfTopRow > 0 && shiftDownOfTopRow < mScreenRows) {
218	            // Shrinking. Check if we can skip blank rows at bottom below cursor.
219	            for (int i = mScreenRows - 1; i > 0; i--) {
220	                if (cursor[1] >= i) break;
221	                int r = externalToInternalRow(i);
222	                if (mLines[r] == null || mLines[r].isBlank()) {
223	                    if (--shiftDownOfTopRow == 0) break;
224	                }
225	            }
226	        } else if (shiftDownOfTopRow < 0) {
227	            // Negative shift down = expanding. Only move screen up if there is transcript to show:
228	            int actualShift = Math.max(shiftDownOfTopRow, -mActiveTranscriptRows);
229	            if (shiftDownOfTopRow != actualShift) {
230	                // The new lines revealed by the resizing are not all from the transcript. Blank the below ones.
231	                for (int i = 0; i < actualShift - shiftDownOfTopRow; i++)
232	                    allocateFullLineIfNecessary((mScreenFirstRow + mScreenRows + i) % mTotalRows).clear(currentStyle);
233	                shiftDownOfTopRow = actualShift;
234	            }
235	        }
236	        mScreenFirstRow += shiftDownOfTopRow;
237	        mScreenFirstRow = (mScreenFirstRow < 0) ? (mScreenFirstRow + mTotalRows) : (mScreenFirstRow % mTotalRows);
238	        mTotalRows = newTotalRows;
239	        mActiveTranscriptRows = altScreen ? 0 : Math.max(0, mActiveTranscriptRows + shiftDownOfTopRow);
240	        cursor[1] -= shiftDownOfTopRow;
241	        mScreenRows = newRows;
242	    }
243	
244	    /** Full reflow resize: column count changed (or newRows > mTotalRows). Rewraps all lines. */
245	    private void resizeWithReflow(int newColumns, int newRows, int newTotalRows, int[] cursor, long currentStyle) {
246	        // Copy away old state and update new:
247	        TerminalRow[] oldLines = mLines;
248	        mLines = new TerminalRow[newTotalRows];
249	        for (int i = 0; i < newTotalRows; i++)
250	            mLines[i] = new TerminalRow(newColumns, currentStyle);
251	
252	        final int oldActiveTranscriptRows = mActiveTranscriptRows;
253	        final int oldScreenFirstRow = mScreenFirstRow;
254	        final int oldScreenRows = mScreenRows;
255	        final int oldTotalRows = mTotalRows;
256	        mTotalRows = newTotalRows;
257	        mScreenRows = newRows;
258	        mActiveTranscriptRows = mScreenFirstRow = 0;
259	        mColumns = newColumns;
260	
261	        int oldCursorRow = cursor[1];
262	        int oldCursorColumn = cursor[0];
263	        ReflowState state = new ReflowState();
264	
265	        // Loop over every character in the initial state.
266	        // Blank lines should be skipped only if at end of transcript (just as is done in the "fast" resize), so we
267	        // keep track how many blank lines we have skipped if we later on find a non-blank line.
268	        int skippedBlankLines = 0;
269	        for (int externalOldRow = -oldActiveTranscriptRows; externalOldRow < oldScreenRows; externalOldRow++) {
270	            // Do what externalToInternalRow() does but for the old state:
271	            int internalOldRow = oldScreenFirstRow + externalOldRow;
272	            internalOldRow = (internalOldRow < 0) ? (oldTotalRows + internalOldRow) : (internalOldRow % oldTotalRows);
273	
274	            TerminalRow oldLine = oldLines[internalOldRow];
275	            boolean cursorAtThisRow = externalOldRow == oldCursorRow;
276	            // The cursor may only be on a non-null line, which we should not skip:
277	            if (oldLine == null || (!(!state.cursorPlaced && cursorAtThisRow)) && oldLine.isBlank()) {
278	                skippedBlankLines++;
279	                continue;
280	            } else if (skippedBlankLines > 0) {
281	                // After skipping some blank lines we encounter a non-blank line. Insert the skipped blank lines.
282	                for (int i = 0; i < skippedBlankLines; i++)
283	                    advanceReflowRow(state, false, currentStyle);
284	                skippedBlankLines = 0;
285	            }
286	
287	            int lastNonSpaceIndex = 0;
288	            boolean justToCursor = false;
289	            if (cursorAtThisRow || oldLine.mLineWrap) {
290	                // Take the whole line, either because of cursor on it, or if line wrapping.
291	                lastNonSpaceIndex = oldLine.getSpaceUsed();
292	                if (cursorAtThisRow) justToCursor = true;
293	            } else {
294	                for (int i = 0; i < oldLine.getSpaceUsed(); i++)
295	                    // NEWLY INTRODUCED BUG! Should not index oldLine.mStyle with char indices
296	                    if (oldLine.mText[i] != ' '/* || oldLine.mStyle[i] != currentStyle */)
297	                        lastNonSpaceIndex = i + 1;
298	            }
299	
300	            reflowOldRow(oldLine, lastNonSpaceIndex, justToCursor, externalOldRow, oldCursorRow, oldCursorColumn, state, currentStyle);
301	
302	            // Old row has been copied. Check if we need to insert newline if old line was not wrapping:
303	            if (externalOldRow != (oldScreenRows - 1) && !oldLine.mLineWrap)
304	                advanceReflowRow(state, true, currentStyle);
305	        }
306	
307	        cursor[0] = state.newCursorColumn;
308	        cursor[1] = state.newCursorRow;
309	    }
310	
311	    /** Mutable state threaded through the reflow helpers to avoid 5 separate locals in resizeWithReflow. */
312	    private static final class ReflowState {
313	        int outputRow;
314	        int outputColumn;
315	        int newCursorRow = -1;
316	        int newCursorColumn = -1;
317	        boolean cursorPlaced;
318	    }
319	
320	    /**
321	     * Advance to the next output row during reflow (scroll or increment), resetting the output column.
322	     * When {@code adjustPlacedCursor} is true and the cursor has already been placed on a prior char,
323	     * decrement newCursorRow to compensate for the scroll (faithful to the original inline blocks).
324	     * Blank-line flushing uses false because it did not apply this adjustment in the original code.
325	     */
326	    private void advanceReflowRow(ReflowState state, boolean adjustPlacedCursor, long currentStyle) {
327	        if (state.outputRow == mScreenRows - 1) {
328	            if (adjustPlacedCursor && state.cursorPlaced) state.newCursorRow--;
329	            scrollDownOneLine(0, mScreenRows, currentStyle);
330	        } else {
331	            state.outputRow++;
332	        }
333	        state.outputColumn = 0;
334	    }
335	
336	    /** Process one old source row's characters into the reflow output, updating {@code state} in place. */
337	    private void reflowOldRow(TerminalRow oldLine, int lastNonSpaceIndex, boolean justToCursor,
338	                               int externalOldRow, int oldCursorRow, int oldCursorColumn,
339	                               ReflowState state, long currentStyle) {
340	        int currentOldCol = 0;
341	        long styleAtCol = 0;
342	        for (int i = 0; i < lastNonSpaceIndex; i++) {
343	            // Note that looping over java character, not cells.
344	            char c = oldLine.mText[i];
345	            int codePoint = (Character.isHighSurrogate(c)) ? Character.toCodePoint(c, oldLine.mText[++i]) : c;
346	            int displayWidth = WcWidth.width(codePoint);
347	            // Use the last style if this is a zero-width character:
348	            if (displayWidth > 0) styleAtCol = oldLine.getStyle(currentOldCol);
349	
350	            // Line wrap as necessary:
351	            if (state.outputColumn + displayWidth > mColumns) {
352	                setLineWrap(state.outputRow);
353	                advanceReflowRow(state, true, currentStyle);
354	            }
355	
356	            int offsetDueToCombiningChar = ((displayWidth <= 0 && state.outputColumn > 0) ? 1 : 0);
357	            setChar(state.outputColumn - offsetDueToCombiningChar, state.outputRow, codePoint, styleAtCol);
358	
359	            if (displayWidth > 0) {
360	                if (oldCursorRow == externalOldRow && oldCursorColumn == currentOldCol) {
361	                    state.newCursorColumn = state.outputColumn;
362	                    state.newCursorRow = state.outputRow;
363	                    state.cursorPlaced = true;
364	                }
365	                currentOldCol += displayWidth;
366	                state.outputColumn += displayWidth;
367	                if (justToCursor && state.cursorPlaced) break;
368	            }
369	        }
370	    }
371	
372	    /**
373	     * Block copy lines and associated metadata from one location to another in the circular buffer, taking wraparound
374	     * into account.
375	     *
376	     * @param srcInternal The first line to be copied.
377	     * @param len         The number of lines to be copied.
378	     */
379	    private void blockCopyLinesDown(int srcInternal, int len) {
380	        if (len == 0) return;
381	        int totalRows = mTotalRows;
382	
383	        int start = len - 1;
384	        // Save away line to be overwritten:
385	        TerminalRow lineToBeOverWritten = mLines[(srcInternal + start + 1) % totalRows];
386	        // Do the copy from bottom to top.
387	        for (int i = start; i >= 0; --i)
388	            mLines[(srcInternal + i + 1) % totalRows] = mLines[(srcInternal + i) % totalRows];
389	        // Put back overwritten line, now above the block:
390	        mLines[(srcInternal) % totalRows] = lineToBeOverWritten;
391	    }
392	
393	    /**
394	     * Scroll the screen down one line. To scroll the whole screen of a 24 line screen, the arguments would be (0, 24).
395	     *
396	     * @param topMargin    First line that is scrolled.
397	     * @param bottomMargin One line after the last line that is scrolled.
398	     * @param style        the style for the newly exposed line.
399	     */
400	    public void scrollDownOneLine(int topMargin, int bottomMargin, long style) {
401	        if (topMargin > bottomMargin - 1 || topMargin < 0 || bottomMargin > mScreenRows)
402	            throw new IllegalArgumentException("topMargin=" + topMargin + ", bottomMargin=" + bottomMargin + ", mScreenRows=" + mScreenRows);
403	
404	        // Copy the fixed topMargin lines one line down so that they remain on screen in same position:
405	        blockCopyLinesDown(mScreenFirstRow, topMargin);
406	        // Copy the fixed mScreenRows-bottomMargin lines one line down so that they remain on screen in same
407	        // position:
408	        blockCopyLinesDown(externalToInternalRow(bottomMargin), mScreenRows - bottomMargin);
409	
410	        // Update the screen location in the ring buffer:
411	        mScreenFirstRow = (mScreenFirstRow + 1) % mTotalRows;
412	        // Note that the history has grown if not already full:
413	        if (mActiveTranscriptRows < mTotalRows - mScreenRows) mActiveTranscriptRows++;
414	
415	        // Blank the newly revealed line above the bottom margin:
416	        int blankRow = externalToInternalRow(bottomMargin - 1);
417	        if (mLines[blankRow] == null) {
418	            mLines[blankRow] = new TerminalRow(mColumns, style);
419	        } else {
420	            mLines[blankRow].clear(style);
421	        }
422	    }
423	
424	    /**
425	     * Block copy characters from one position in the screen to another. The two positions can overlap. All characters
426	     * of the source and destination must be within the bounds of the screen, or else an InvalidParameterException will
427	     * be thrown.
428	     *
429	     * @param sx source X coordinate
430	     * @param sy source Y coordinate
431	     * @param w  width
432	     * @param h  height
433	     * @param dx destination X coordinate
434	     * @param dy destination Y coordinate
435	     */
436	    public void blockCopy(int sx, int sy, int w, int h, int dx, int dy) {
437	        if (w == 0) return;
438	        if (sx < 0 || sx + w > mColumns || sy < 0 || sy + h > mScreenRows || dx < 0 || dx + w > mColumns || dy < 0 || dy + h > mScreenRows)
439	            throw new IllegalArgumentException();
440	        boolean copyingUp = sy > dy;
441	        for (int y = 0; y < h; y++) {
442	            int y2 = copyingUp ? y : (h - (y + 1));
443	            TerminalRow sourceRow = allocateFullLineIfNecessary(externalToInternalRow(sy + y2));
444	            allocateFullLineIfNecessary(externalToInternalRow(dy + y2)).copyInterval(sourceRow, sx, sx + w, dx);
445	        }
446	    }
447	
448	    /**
449	     * Block set characters. All characters must be within the bounds of the screen, or else and
450	     * InvalidParemeterException will be thrown. Typically this is called with a "val" argument of 32 to clear a block
451	     * of characters.
452	     */
453	    public void blockSet(int sx, int sy, int w, int h, int val, long style) {
454	        if (sx < 0 || sx + w > mColumns || sy < 0 || sy + h > mScreenRows) {
455	            throw new IllegalArgumentException(
456	                "Illegal arguments! blockSet(" + sx + ", " + sy + ", " + w + ", " + h + ", " + val + ", " + mColumns + ", " + mScreenRows + ")");
457	        }
458	        for (int y = 0; y < h; y++)
459	            for (int x = 0; x < w; x++)
460	                setChar(sx + x, sy + y, val, style);
461	    }
462	
463	    public TerminalRow allocateFullLineIfNecessary(int row) {
464	        return (mLines[row] == null) ? (mLines[row] = new TerminalRow(mColumns, 0)) : mLines[row];
465	    }
466	
467	    public void setChar(int column, int row, int codePoint, long style) {
468	        if (row  < 0 || row >= mScreenRows || column < 0 || column >= mColumns)
469	            throw new IllegalArgumentException("TerminalBuffer.setChar(): row=" + row + ", column=" + column + ", mScreenRows=" + mScreenRows + ", mColumns=" + mColumns);
470	        row = externalToInternalRow(row);
471	        allocateFullLineIfNecessary(row).setChar(column, codePoint, style);
472	    }
473	
474	    public long getStyleAt(int externalRow, int column) {
475	        return allocateFullLineIfNecessary(externalToInternalRow(externalRow)).getStyle(column);
476	    }
477	
478	    /** Support for http://vt100.net/docs/vt510-rm/DECCARA and http://vt100.net/docs/vt510-rm/DECCARA */
479	    public void setOrClearEffect(int bits, boolean setOrClear, boolean reverse, boolean rectangular, int leftMargin, int rightMargin, int top, int left,
480	                                 int bottom, int right) {
481	        for (int y = top; y < bottom; y++) {
482	            TerminalRow line = mLines[externalToInternalRow(y)];
483	            int startOfLine = (rectangular || y == top) ? left : leftMargin;
484	            int endOfLine = (rectangular || y + 1 == bottom) ? right : rightMargin;
485	            for (int x = startOfLine; x < endOfLine; x++) {
486	                long currentStyle = line.getStyle(x);
487	                int foreColor = TextStyle.decodeForeColor(currentStyle);
488	                int backColor = TextStyle.decodeBackColor(currentStyle);
489	                int effect = TextStyle.decodeEffect(currentStyle);
490	                if (reverse) {
491	                    // Clear out the bits to reverse and add them back in reversed:
492	                    effect = (effect & ~bits) | (bits & ~effect);
493	                } else if (setOrClear) {
494	                    effect |= bits;
495	                } else {
496	                    effect &= ~bits;
497	                }
498	                line.mStyle[x] = TextStyle.encode(foreColor, backColor, effect);
499	            }
500	        }
501	    }
502	
503	    public void clearTranscript() {
504	        if (mScreenFirstRow < mActiveTranscriptRows) {
505	            Arrays.fill(mLines, mTotalRows + mScreenFirstRow - mActiveTranscriptRows, mTotalRows, null);
506	            Arrays.fill(mLines, 0, mScreenFirstRow, null);
507	        } else {
508	            Arrays.fill(mLines, mScreenFirstRow - mActiveTranscriptRows, mScreenFirstRow, null);
509	        }
510	        mActiveTranscriptRows = 0;
511	    }
512	
513	}
