private void doCsiDecModesSaveOrRestore(int b) {
    if (mArgIndex >= mArgs.length) mArgIndex = mArgs.length - 1;
    for (int i = 0; i <= mArgIndex; i++) {
        int externalBit = mArgs[i];
        int internalBit = mapDecSetBitToInternalBit(externalBit);
        if (internalBit == -1) {
